    static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static CardInstance hand(ServerMatch m,UUID p){return DynamicPassiveModifierTest.hand(m,p,"trainer");}
    static TrainerProfile profile(){return NonPokemonBatch2Test.DATA.trainer(IDS.getFirst()).orElseThrow();}
    static GeneratedRuleBatch28Test.Config config(){var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile();c.attack=GeneratedRuleBatch8Test.hit(300,false);c.defenderAttack=c.attack;return c;}
    static ServerMatch game(){return GeneratedRuleBatch28Test.fixture(config());}
    static void top(ServerMatch m,UUID p,CardInstance card){check(PairedTrainerPlayTest.zone(m,p,"hand").remove(card),"Top setup card not in hand");PairedTrainerPlayTest.zone(m,p,"deck").add(card);}
    record Draw(ServerMatch match,UUID owner,CardInstance card,int handSize,int remaining) { }
    static Draw prepare(ServerMatch m,UUID p,int remaining,boolean attack){if(p.equals(A)){m.endTurn(A);GeneratedRuleBatch28Test.finishIncidentalTurnDraw(m);}var card=hand(m,p);top(m,p,card);var deck=PairedTrainerPlayTest.zone(m,p,"deck");var discard=PairedTrainerPlayTest.zone(m,p,"discard");if(remaining>=0)while(deck.size()>remaining+1)discard.add(deck.removeFirst());int held=m.privateView(p).hand().size(),left=deck.size()-1;if(attack)m.attack(other(p),"hit");else m.endTurn(other(p));return new Draw(m,p,card,held,left);}
    static ServerMatch aiGame(String id){return prepare(game(),A,-1,false).match();}
    public static void main(String[] args){drawAndDecline();exclusiveWindow();authority();locksAndListeners();firstTurn();ai();schema();System.out.println("NonPokemonBatch118Test passed: Nugget exact natural-turn-draw before-hand window, both players and first turn, decline and 0/1/2/3 remaining cards, no recursive window from effect draws, no hand-only Trainer locks/coin gate/hand-play triggers, exact identity/disposal and no manual quota, private prompt authority and action blocking, concede conservation and four AI difficulties");}
    static void drawAndDecline(){for(UUID p:List.of(A,B))for(boolean use:List.of(false,true))for(int left=0;left<=3;left++){
        var f=prepare(game(),p,left,false);var m=f.match();var opponent=m.privateView(other(p));if(left==0){check(!m.hasPendingDrawnTrainer()&&m.privateView(p).hand().contains(f.card())&&m.phase()==MatchPhase.TURN,"Last deck card Nugget opened unusable draw or caused early deck-out");continue;}check(m.hasPendingDrawnTrainer(p)&&m.hasPendingTurnDraw()&&m.privateView(p).hand().size()==f.handSize()&&!m.privateView(p).hand().contains(f.card()),"Drawn Nugget prematurely entered hand");var q=m.drawnTrainerPrompt(p);m.decideDrawnTrainer(p,q.id(),use);check(m.privateView(p).hand().size()==f.handSize()+(use?left:1)&&m.privateView(p).discard().contains(f.card())==use&&m.privateView(p).hand().contains(f.card())!=use,"Nugget wrong draw count or physical destination");check(m.privateView(p).deck().size()==(use?0:left)&&m.privateView(other(p)).equals(opponent)&&!m.hasPendingTurnDraw()&&!m.energyAttached(p)&&m.phase()==MatchPhase.TURN,"Nugget changed opponent/manual attachment or stalled");if(!use)check(!m.canPlayTrainer(p,f.card().instanceId(),null),"Declined Nugget could later be played from hand");
    }}
    static void exclusiveWindow(){var m=game();var held=hand(m,A);check(!m.canPlayTrainer(A,held.instanceId(),null),"Nugget usable from ordinary hand");reject(()->m.playTrainer(A,held.instanceId(),null));top(m,A,held);m.drawCardsByEffect(A,A,1);check(m.privateView(A).hand().contains(held)&&!m.hasPendingDrawnTrainer(),"Effect draw opened natural draw window");var first=hand(m,A);top(m,A,first);var second=hand(m,A);top(m,A,second);m.drawCardsByEffect(A,A,2);check(!m.hasPendingDrawnTrainer()&&!m.canPlayTrainer(A,second.instanceId(),null),"Multiple effect draws allowed Nugget play");}
    static void authority(){var f=prepare(game(),B,3,false);var m=f.match();var q=m.drawnTrainerPrompt(B);var before=m.clientView(B);var rng=m.randomTranscript();reject(()->m.drawnTrainerPrompt(A));reject(()->m.decideDrawnTrainer(A,q.id(),true));reject(()->m.decideDrawnTrainer(B,UUID.randomUUID(),true));reject(()->m.endTurn(B));reject(()->m.attachEnergy(B,DynamicPassiveModifierTest.hand(m,B,"energy").instanceId(),m.activePokemonView(B).pokemonId()));check(!m.mayAttack(B)&&!m.mayPlaySupporter(B)&&before.equals(m.clientView(B))&&rng.equals(m.randomTranscript()),"Invalid natural-draw action changed state or another turn action remained enabled");var session=MatchSession.multiplayer(m,A,B);check(session.view(B,B).options().stream().filter(o->o.type()==ActionType.LUCKY_USE).count()==1&&session.view(A,A).options().stream().noneMatch(o->o.type()==ActionType.LUCKY_USE||o.type()==ActionType.LUCKY_SKIP),"Wrong owner received draw-card decisions");m.decideDrawnTrainer(B,q.id(),false);reject(()->m.decideDrawnTrainer(B,q.id(),true));var n=prepare(game(),A,3,false);n.match().concede(B);check(n.match().phase()==MatchPhase.FINISHED&&!n.match().hasPendingTurnDraw()&&n.match().privateView(A).hand().contains(n.card()),"Concede lost held natural-draw card");}
    static void locksAndListeners(){var c=config();c.attack=DeckDiscardTriggeredAbilityTest.attack(10,TrainerPlayLockTest.lock("ITEM")+",{\"type\":\"trainer_attempt_coin_gate\",\"target\":\"OPPONENT_ACTIVE\",\"scope\":\"PLAYER\",\"source\":\"HAND\",\"on_tails\":\"DISCARD_INSTEAD_OF_USE\",\"duration\":\"OPPONENT_NEXT_TURN\"}");var m=GeneratedRuleBatch28Test.fixture(c);var f=prepare(m,B,3,true);check(m.trainerPlayLocked(B,"trainer")&&m.hasPendingDrawnTrainer(B),"Hand-only Item lock incorrectly prevented Nugget window");var rng=m.randomTranscript();m.decideDrawnTrainer(B,m.drawnTrainerPrompt(B).id(),true);check(m.privateView(B).hand().size()==f.handSize()+3&&m.randomTranscript().equals(rng),"Nugget paid hand-only coin gate or failed draw under lock");
        var watcher=config();watcher.ownAbility=BundledCombatData.ability(JsonParser.parseString("{\"id\":\"nugget-watch\",\"nameZh\":\"手牌物品监听\",\"kind\":\"TRIGGERED\",\"effectSupport\":\"SUPPORTED\",\"eventPolicy\":{\"trigger\":\"ON_CARD_PLAYED\",\"player\":\"SELF\",\"card\":\"ITEM\",\"optional\":false,\"usage\":\"NONE\"},\"effects\":[{\"type\":\"draw\",\"target\":\"SELF\",\"amount\":1}]}").getAsJsonObject(),EffectRegistry.standard());var w=prepare(GeneratedRuleBatch28Test.fixture(watcher),A,-1,false);int history=GeneratedRuleBatch53Test.history(w.match(),"handPlays").size();w.match().decideDrawnTrainer(A,w.match().drawnTrainerPrompt(A).id(),true);NonPokemonBatch103Test.settle(w.match());check(w.match().privateView(A).hand().size()==w.handSize()+3&&GeneratedRuleBatch53Test.history(w.match(),"handPlays").size()==history,"Before-hand Nugget invented a hand play/listener trigger");
    }
    static void firstTurn(){var defs=List.of(new CardDefinition("basic","基础",CardCategory.POKEMON,TrainerCategory.NONE,"H",Set.of("international"),true,false,60,Map.of(),EffectSupport.SUPPORTED,null),new CardDefinition("trainer","金珠",CardCategory.TRAINER,TrainerCategory.ITEM,"H",Set.of("international"),false,false,60,Map.of(),EffectSupport.SUPPORTED,null));var pokemon=new PokemonProfile(300,0,null,null,0,null,0,1,List.of(GeneratedRuleBatch8Test.hit(100,false)),List.of(),EnergyType.COLORLESS);var combat=new CombatCatalog(Map.of("basic",pokemon),Map.of(),Map.of("trainer",profile()),Map.of());for(int seed=0;seed<100;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,i%2==0?"basic":"trainer"));decks.add(cards);}var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.complete(m,A,B,0);if(!m.hasPendingDrawnTrainer())continue;int held=m.privateView(A).hand().size();check(m.currentPlayer().equals(A)&&m.turnNumber()==1,"Opening fixture is not first player's first turn");m.decideDrawnTrainer(A,m.drawnTrainerPrompt(A).id(),true);check(m.privateView(A).hand().size()==held+3&&!m.hasPendingDrawnTrainer(),"First-turn Nugget could not finish");return;}throw new AssertionError("No first-turn Nugget fixture");}
    static void ai(){for(var difficulty:AiDifficulty.values()){var m=aiGame(IDS.getFirst());var s=MatchSession.multiplayer(m,A,B);AiCardOperationTest.settle(s,difficulty);AiCardOperationTest.finish(s,difficulty);check(m.phase()==MatchPhase.FINISHED,"Nugget AI stalled: "+difficulty);}}
